use vstd::prelude::*;

verus! {

spec fn divides(n: int, d: int) -> bool {
    d != 0 && n % d == 0
}

spec fn is_proper_divisor(n: int, d: int) -> bool {
    1 <= d && d < n && divides(n, d)
}

spec fn is_largest_proper_divisor(n: int, d: int) -> bool {
    is_proper_divisor(n, d) &&
    forall|k: int| (d < k && k < n) ==> !divides(n, k)
}

fn largest_divisor(n: i8) -> i8
    requires
        n > 1,
    ensures
        is_largest_proper_divisor(n as int, result as int)
{
    let mut d: i8 = n - 1;
    while d > 0
        invariant
            1 <= d + 1 && d + 1 < n,
            // no divisor k with d + 1 < k < n divides n
            forall|k: int| (d + 1 < k && k < n as int) ==> !divides(n as int, k),
        decreases d,
    {
        if (n % d) == 0 {
            return d;
        }
        d -= 1;
    }
    // fallback: since n > 1, 1 divides n, so we return 1
    1
}

}
